def current_rows(events):
    latest = {}
    for e in events:
        id = e['id']
        key = (e['event_time'], e['seq'])
        if id not in latest or key > latest[id][0]:
            latest[id] = (key, e)

    result = []
    for _, e in latest.values():
        if e['op'] != 'D':
            result.append({'id': e['id'], 'value': e['value']})

    result.sort(key=lambda x: x['id'])
    return result
