import heapq

def stable_toposort(graph):
    """
    Return a dependency-first topological order of the graph.

    The graph is a dict mapping each node to an iterable of its dependencies.
    The order respects the original insertion order of the dict when multiple
    nodes are ready (i.e., all their dependencies have been processed).

    Raises:
        ValueError: If a dependency is missing from the graph or if a cycle is detected.
    """
    # Validate all dependencies exist
    for node, deps in graph.items():
        for dep in deps:
            if dep not in graph:
                raise ValueError(f"Missing dependency: {dep} (required by {node})")

    # Build in-degree and reverse adjacency
    in_degree = {node: 0 for node in graph}
    reverse = {node: [] for node in graph}
    for node, deps in graph.items():
        for dep in deps:
            in_degree[node] += 1
            reverse[dep].append(node)

    # Assign insertion index (0-based) to each node
    index = {node: i for i, node in enumerate(graph)}

    # Min-heap of (index, node) for nodes with in-degree 0
    heap = []
    for node, deg in in_degree.items():
        if deg == 0:
            heapq.heappush(heap, (index[node], node))

    result = []
    while heap:
        _, node = heapq.heappop(heap)
        result.append(node)
        for succ in reverse[node]:
            in_degree[succ] -= 1
            if in_degree[succ] == 0:
                heapq.heappush(heap, (index[succ], succ))

    if len(result) != len(graph):
        raise ValueError("Cycle detected in dependency graph")

    return result
