def schema_drift(expected, actual):
    def flatten(obj, prefix=""):
        flat = {}
        for key, value in obj.items():
            path = f"{prefix}.{key}" if prefix else key
            if isinstance(value, dict):
                flat.update(flatten(value, path))
            else:
                flat[path] = value
        return flat

    exp_flat = flatten(expected)
    act_flat = flatten(actual)

    missing = set(exp_flat.keys()) - set(act_flat.keys())
    extra = set(act_flat.keys()) - set(exp_flat.keys())
    type_diff = {
        key for key in exp_flat
        if key in act_flat and exp_flat[key] != act_flat[key]
    }

    return sorted(missing | extra | type_diff)
