def merge_payload_ranges(items):
    # Filter valid intervals and group by payload
    groups = {}
    for start, end, payload in items:
        if start > end:
            continue  # reject invalid
        groups.setdefault(payload, []).append((start, end))

    result = []
    for payload, intervals in groups.items():
        # Sort intervals by start, then end
        intervals.sort(key=lambda x: (x[0], x[1]))
        merged = []
        for start, end in intervals:
            if not merged or start > merged[-1][1] + 1:
                merged.append([start, end])
            else:
                merged[-1][1] = max(merged[-1][1], end)
        for start, end in merged:
            result.append([start, end, payload])

    # Sort final result by start and end for consistency
    result.sort(key=lambda x: (x[0], x[1]))
    return result
